// ===== scoring/weights.ts =====
export const DEFAULT_WEIGHTS: Weights = {
  bookingIntentAuthority: 25,
  provenWinterActivity: 20,
  audienceRelevance: 15,
  estimatedVenueBudget: 15,
  geographicFit: 10,
  expectedStayDuration: 5,
  engagementQuality: 5,
  partnershipFeasibility: 5,
};

export const WEIGHT_LABELS: Record<keyof Weights, string> = {
  bookingIntentAuthority: 'Booking intent and decision-making authority',
  provenWinterActivity: 'Proven winter activity',
  audienceRelevance: 'Audience relevance',
  estimatedVenueBudget: 'Estimated venue budget',
  geographicFit: 'Geographic fit',
  expectedStayDuration: 'Expected stay duration',
  engagementQuality: 'Engagement quality',
  partnershipFeasibility: 'Partnership feasibility',
};

/** Normalise any set of non-negative weights so they sum to exactly 100 (largest remainder rounding). */
export function normalizeWeights(w: Partial<Weights>): Weights {
  const keys = Object.keys(DEFAULT_WEIGHTS) as Array<keyof Weights>;
  const raw = keys.map((k) => Math.max(0, Number(w[k] ?? DEFAULT_WEIGHTS[k])));
  const total = raw.reduce((a, b) => a + b, 0);
  if (total === 0) return { ...DEFAULT_WEIGHTS };
  const scaled = raw.map((v) => (v / total) * 100);
  const floored = scaled.map(Math.floor);
  let remainder = 100 - floored.reduce((a, b) => a + b, 0);
  const order = scaled.map((v, i) => ({ i, frac: v - floored[i] })).sort((a, b) => b.frac - a.frac);
  for (const { i } of order) { if (remainder <= 0) break; floored[i] += 1; remainder -= 1; }
  const out = {} as Weights;
  keys.forEach((k, i) => { out[k] = floored[i]; });
  return out;
}

// ===== scoring/budget.ts =====
/**
 * Venue budget estimation.
 *
 * The villa is priced by proposal, so we estimate what an organiser can pay
 * for the venue from her event economics. The 35% share is a sensitivity
 * assumption supplied by the owner, not an industry fact; it is editable.
 */

export interface BudgetInputs {
  participants?: number | null;          // expected or published group size
  pricePerParticipant?: number | null;   // EUR
  nights?: number | null;
  priorVenueBudget?: number | null;      // EUR per event, if ever disclosed
  venueShare?: number;                   // default 0.35
  provenance: Provenance;
}

export interface BudgetEstimate {
  eventRevenueEur: number | null;
  venueBudgetEur: number | null;         // per event
  venueBudgetPerNightEur: number | null;
  meetsFloor: boolean | null;
  floorPricePerNightEur: number;
  assumptions: string[];
  provenance: Provenance;
  /** Conservative / base / optimistic per-night budgets. */
  scenarios: { conservative: number | null; base: number | null; optimistic: number | null };
}

export function estimateVenueBudget(input: BudgetInputs, floorPricePerNightEur = COMMERCIAL_DEFAULTS.floorPricePerNightEur): BudgetEstimate {
  const share = input.venueShare ?? COMMERCIAL_DEFAULTS.venueBudgetShareOfRevenue;
  const assumptions: string[] = [`Venue share of event revenue assumed at ${(share * 100).toFixed(0)}% (sensitivity assumption, editable).`];
  const nights = input.nights ?? null;

  if (input.priorVenueBudget != null && input.priorVenueBudget > 0) {
    const perNight = nights ? input.priorVenueBudget / nights : null;
    assumptions.push('Prior venue budget disclosed by the organiser; used directly.');
    return {
      eventRevenueEur: null,
      venueBudgetEur: input.priorVenueBudget,
      venueBudgetPerNightEur: perNight,
      meetsFloor: perNight == null ? null : perNight >= floorPricePerNightEur,
      floorPricePerNightEur,
      assumptions,
      provenance: input.provenance,
      scenarios: { conservative: perNight == null ? null : perNight * 0.8, base: perNight, optimistic: perNight == null ? null : perNight * 1.15 },
    };
  }

  if (input.participants == null || input.pricePerParticipant == null || input.participants <= 0 || input.pricePerParticipant <= 0) {
    return { eventRevenueEur: null, venueBudgetEur: null, venueBudgetPerNightEur: null, meetsFloor: null, floorPricePerNightEur, assumptions: [...assumptions, 'Participants or price per participant unknown; no estimate.'], provenance: 'unknown', scenarios: { conservative: null, base: null, optimistic: null } };
  }

  const revenue = input.participants * input.pricePerParticipant;
  const venue = revenue * share;
  const perNight = nights ? venue / nights : null;
  if (!nights) assumptions.push('Event length unknown; per-night budget not computed.');
  const cons = perNight == null ? null : (revenue * Math.max(0.2, share - 0.1)) / (nights as number);
  const opt = perNight == null ? null : (revenue * Math.min(0.5, share + 0.1)) / (nights as number);
  return {
    eventRevenueEur: revenue,
    venueBudgetEur: venue,
    venueBudgetPerNightEur: perNight,
    meetsFloor: perNight == null ? null : perNight >= floorPricePerNightEur,
    floorPricePerNightEur,
    assumptions,
    provenance: input.provenance === 'verified_public_fact' ? 'evidence_supported_inference' : input.provenance === 'unknown' ? 'ai_estimate' : input.provenance,
    scenarios: { conservative: cons, base: perNight, optimistic: opt },
  };
}

type BudgetEvent = { role: string; pricePerPerson?: number | null; currency?: string | null; groupSize?: number | null; nights?: number | null; provenance?: Provenance };
const med = (xs: number[]): number | null => { if (!xs.length) return null; const s = [...xs].sort((a, b) => a - b); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

/**
 * Budget inputs from an organiser's published events. Organisers rarely publish price and
 * group size on the same post, so: price = highest published EUR price per person; group =
 * that event's size, else the median published size, else the villa's capacity (stated as an
 * assumption). Groups larger than the villa are capped at its capacity. Prices in other
 * currencies are not converted; the note says so and no estimate is made.
 */
export function budgetInputsFromEvents(events: BudgetEvent[], capacity: number = VILLA.groupCapacity.value): { inputs: BudgetInputs; notes: string[] } {
  const org = events.filter((e) => e.role === 'organizer' || e.role === 'co_host');
  const pool = org.length ? org : events;
  const notes: string[] = [];
  const priced = pool.filter((e) => typeof e.pricePerPerson === 'number' && e.pricePerPerson > 0);
  const eur = priced.filter((e) => (e.currency ?? '').toUpperCase() === 'EUR').sort((a, b) => (b.pricePerPerson as number) - (a.pricePerPerson as number));
  if (priced.length && !eur.length) notes.push(`Published price is in ${Array.from(new Set(priced.map((e) => e.currency ?? 'an unstated currency'))).join('/')}; not converted, so no budget estimate.`);
  const best = eur[0];
  if (!best) return { inputs: { participants: null, pricePerParticipant: null, nights: null, provenance: 'unknown' }, notes };
  let participants = best.groupSize ?? med(pool.map((e) => e.groupSize).filter((n): n is number => typeof n === 'number' && n > 0));
  let provenance: Provenance = best.provenance ?? 'unknown';
  if (participants == null) {
    participants = capacity; provenance = 'ai_estimate';
    notes.push(`Group size not published; assumed the group fills the villa (${capacity} guests${VILLA.groupCapacity.verified ? '' : ', capacity unverified'}).`);
  } else if (participants > capacity) {
    notes.push(`Published group of ${participants} exceeds the villa's ${capacity} guests; capped at capacity.`);
    participants = capacity;
  }
  const nights = best.nights ?? med(pool.map((e) => e.nights).filter((n): n is number => typeof n === 'number' && n > 0));
  return { inputs: { participants, pricePerParticipant: best.pricePerPerson as number, nights, provenance }, notes };
}

// ===== scoring/ebn.ts =====
/**
 * Expected Booked Nights (primary objective) and Expected Net Commercial Value
 * (secondary). Probabilities here are computed, never empirically verified;
 * the output says so and carries scenarios.
 */

export interface EbnInputs {
  score: ScoreResult;
  /** Nights per event the organiser typically runs (published event lengths). */
  typicalNights?: number | null;
  /** Events per year she runs, from evidence. */
  eventsPerYear?: number | null;
  /** Fraction of her events that fall in Nov–Apr, from evidence. */
  winterShare?: number | null;
  /** Estimated nightly revenue the villa would realise, EUR. */
  nightlyRevenueEur?: number | null;
  track: PartnershipTrack;
  /** Does private verified data back these inputs? */
  verified: boolean;
  /**
   * Estimated venue budget per night divided by the floor price (null when unknown).
   * Below 1 the group cannot pay the floor price, so the booking probability is scaled
   * by this ratio (minimum 0.1). Unknown budgets leave the probability unchanged.
   */
  budgetToFloorRatio?: number | null;
}

type EventLike = { role: string; startDate?: string | null; nights?: number | null; isWinter?: boolean };

/**
 * Event-derived EBN inputs. Events per year is the busiest single season window
 * (1 Nov to 31 Oct), so posts from several past seasons are not added together.
 * Undated events cannot be placed in a window; they count only if they exceed the busiest window.
 */
export function eventInputs(events: EventLike[]): { typicalNights: number | null; eventsPerYear: number | null; winterShare: number | null } {
  const org = events.filter((e) => e.role === 'organizer' || e.role === 'co_host');
  if (!org.length) return { typicalNights: null, eventsPerYear: null, winterShare: null };
  const nights = org.map((e) => e.nights).filter((n): n is number => typeof n === 'number' && n > 0).sort((a, b) => a - b);
  const m = Math.floor(nights.length / 2);
  const typicalNights = nights.length ? (nights.length % 2 ? nights[m] : (nights[m - 1] + nights[m]) / 2) : null;
  const windows = new Map<number, number>();
  let undated = 0;
  for (const e of org) {
    const d = /^(\d{4})-(\d{2})/.exec(e.startDate ?? '');
    if (!d) { undated++; continue; }
    const y = Number(d[1]); const mo = Number(d[2]);
    const key = mo >= 11 ? y : y - 1;
    windows.set(key, (windows.get(key) ?? 0) + 1);
  }
  const busiest = windows.size ? Math.max(...windows.values()) : 0;
  const eventsPerYear = Math.max(busiest, undated) || null;
  return { typicalNights, eventsPerYear, winterShare: org.filter((e) => e.isWinter).length / org.length };
}

export interface EbnResult {
  bookingProbability: { conservative: number; base: number; optimistic: number };
  expectedNightsPerEvent: number;
  expectedEventsInSeason: { conservative: number; base: number; optimistic: number };
  expectedBookedNights: { conservative: number; base: number; optimistic: number };
  expectedNetValueEur: { conservative: number | null; base: number | null; optimistic: number | null };
  collaborationCostEur: number;
  probabilityKind: 'computed_not_verified' | 'computed_with_verified_inputs';
  assumptions: string[];
}

/** Map a fit score to a booking probability. Calibration is a logistic curve chosen so 50→~8%, 70→~25%, 85→~50%, 95→~70%. Not empirical. */
export function scoreToProbability(fitScore: number, confidence: number): number {
  const x = (fitScore - 85) / 8;
  const p = 0.72 / (1 + Math.exp(-x));
  // low confidence shrinks toward a prior of 5%
  return 0.05 + (p - 0.05) * (0.4 + 0.6 * confidence);
}

export function expectedBookedNights(input: EbnInputs): EbnResult {
  const assumptions: string[] = [];
  const nights = input.typicalNights ?? 5;
  if (input.typicalNights == null) assumptions.push('Typical event length unknown; assumed 5 nights.');
  const perYear = input.eventsPerYear ?? 1;
  if (input.eventsPerYear == null) assumptions.push('Events per year unknown; assumed 1.');
  const winterShare = input.winterShare ?? 0.3;
  if (input.winterShare == null) assumptions.push('Winter share of events unknown; assumed 30%.');
  let base = scoreToProbability(input.score.fitScore, input.score.confidence);
  const ratio = input.budgetToFloorRatio;
  if (ratio != null && ratio < 1) {
    const f = Math.max(0.1, ratio);
    base *= f;
    assumptions.push(`Estimated venue budget is ${(ratio * 100).toFixed(0)}% of the floor price; booking probability scaled by ${f.toFixed(2)}.`);
  } else if (ratio == null) assumptions.push('Venue budget unknown; booking probability not adjusted for affordability.');
  const prob = { conservative: Math.max(0.01, base * 0.5), base, optimistic: Math.min(0.9, base * 1.4) };
  // Events in a 6-month season = perYear * winterShare; anchor partnerships may add a repeat
  const seasonEvents = perYear * winterShare;
  const repeatBoost = input.track === 'anchor_partnership' ? 1.5 : input.track === 'pilot_retreat' ? 1.1 : 1.0;
  const events = { conservative: Math.max(0.25, seasonEvents * 0.7), base: Math.max(0.5, seasonEvents) * repeatBoost, optimistic: Math.max(1, seasonEvents * 1.5) * repeatBoost };
  const ebn = {
    conservative: prob.conservative * nights * events.conservative,
    base: prob.base * nights * events.base,
    optimistic: prob.optimistic * nights * events.optimistic,
  };
  const cost = COMMERCIAL_DEFAULTS.collaborationCostEur[input.track] ?? 0;
  const rev = input.nightlyRevenueEur ?? null;
  if (rev == null) assumptions.push('Nightly revenue not set; net value not computed.');
  const net = {
    conservative: rev == null ? null : ebn.conservative * rev * 0.85 - cost,
    base: rev == null ? null : ebn.base * rev - cost,
    optimistic: rev == null ? null : ebn.optimistic * rev * 1.1 - cost,
  };
  return {
    bookingProbability: prob,
    expectedNightsPerEvent: nights,
    expectedEventsInSeason: events,
    expectedBookedNights: ebn,
    expectedNetValueEur: net,
    collaborationCostEur: cost,
    probabilityKind: input.verified ? 'computed_with_verified_inputs' : 'computed_not_verified',
    assumptions,
  };
}

// ===== scoring/score.ts =====
/**
 * Commercial scoring engine: 0–100 fit score with dynamic weights, hard gates
 * and confidence. Pure function of a candidate snapshot; the same code runs in
 * the edge function and in local tests.
 */

export interface ScoringOptions {
  weights?: Partial<Weights>;
  floorPricePerNightEur?: number;
  venueShare?: number;
  /** Treat the candidate's private insights as present (Stage 2). */
  usePrivateInsights?: boolean;
}

const SEVERE_RED_FLAGS = [/fake follower/i, /scam/i, /fraud/i, /banned/i, /engagement pod/i, /bought followers/i];

function j(v: Judgement | undefined): { score: number; conf: number } {
  if (!v || v.value === null) return { score: 40, conf: 0 };            // unknown → neutral-low, zero confidence
  return { score: v.value ? 100 : 10, conf: Math.max(0, Math.min(1, v.confidence)) };
}

/** Blend a judgement into 0..100 by confidence: unknown pulls toward 40. */
function blend(v: Judgement | undefined): number {
  const { score, conf } = j(v);
  return 40 + (score - 40) * conf;
}

export function scoreCandidate(c: Candidate, opts: ScoringOptions = {}): ScoreResult {
  const weights = normalizeWeights({ ...DEFAULT_WEIGHTS, ...(opts.weights ?? {}) });
  const cl = c.classification;
  const gates: string[] = [];
  const redFlags: string[] = [...(cl?.redFlags ?? [])];
  const pi = opts.usePrivateInsights ? c.privateInsights : undefined;

  // 1. Booking intent & authority: decides venue + sells (not promotes) + group fit
  const intent = cl
    ? 0.5 * blend(cl.decidesVenue) + 0.35 * blend(cl.sellsRetreats) + 0.15 * blend(cl.canFillGroupSize)
    : 30;
  const organizerEvents = c.events.filter((e) => e.role === 'organizer' || e.role === 'co_host').length;
  const intentScore = Math.min(100, intent + Math.min(15, organizerEvents * 5));

  // 2. Proven winter activity: evidence-backed winter events dominate
  const winterEvents = c.events.filter((e) => e.isWinter && (e.role === 'organizer' || e.role === 'co_host'));
  const verifiedWinter = winterEvents.filter((e) => e.provenance === 'verified_public_fact' || e.provenance === 'document_backed' || e.provenance === 'independently_verified');
  let winterScore = cl ? blend(cl.provenWinterActivity) : 30;
  if (verifiedWinter.length >= 2) winterScore = Math.max(winterScore, 95);
  else if (verifiedWinter.length === 1) winterScore = Math.max(winterScore, 80);
  else if (winterEvents.length >= 1) winterScore = Math.max(winterScore, 60);
  const hasWinterEvidence = winterEvents.length > 0 || (cl?.provenWinterActivity.value === true && cl.provenWinterActivity.evidenceUrls.length > 0);

  // 3. Audience relevance: group B signal, premium audience, private geo data
  let audienceScore = cl ? 0.6 * blend(cl.audiencePaysPremium) + 0.4 * (cl.group === 'B_reaches_organizers' ? 100 : cl.group === 'A_retreat_organizer' ? 75 : cl.group === 'C_high_value_host' ? 70 : 30) : 35;
  if (pi?.audienceCountries?.length) {
    const relevant = pi.audienceCountries.filter((a) => (MARKET_FIT[a.country] ?? 0) >= 0.75).reduce((s, a) => s + a.share, 0);
    audienceScore = 0.5 * audienceScore + 50 * Math.min(1, relevant / 0.6);
  }

  // 4. Estimated venue budget
  const fromEvents = budgetInputsFromEvents(c.events).inputs;
  const participants = pi?.registrationsPerEvent?.length ? Math.max(...pi.registrationsPerEvent.map((r) => r.registrations)) : fromEvents.participants ?? null;
  const price = pi?.avgPricePerParticipant?.value ?? fromEvents.pricePerParticipant ?? null;
  const budget = estimateVenueBudget({ participants, pricePerParticipant: price, nights: fromEvents.nights ?? null, venueShare: opts.venueShare, provenance: pi ? 'document_backed' : fromEvents.provenance }, opts.floorPricePerNightEur);
  let budgetScore: number;
  if (budget.venueBudgetPerNightEur == null) budgetScore = cl ? 0.5 * blend(cl.audiencePaysPremium) + 0.5 * blend(cl.priorCommercialEvidence) : 35;
  else {
    const ratio = budget.venueBudgetPerNightEur / budget.floorPricePerNightEur;
    budgetScore = ratio >= 1.5 ? 100 : ratio >= 1 ? 80 : ratio >= 0.7 ? 50 : 20;
  }

  // 5. Geographic fit
  const marketFits = c.markets.map((m) => MARKET_FIT[m] ?? MARKET_FIT.OTHER);
  const geoScore = marketFits.length ? Math.max(...marketFits) * 100 : 40;

  // 6. Expected stay duration
  const maxNights = Math.max(0, ...c.events.map((e) => e.nights ?? 0));
  let stayScore = maxNights >= 10 ? 100 : maxNights >= 6 ? 85 : maxNights >= 4 ? 70 : maxNights > 0 ? 35 : 45;
  if (cl?.longStayPotential.value === true) stayScore = Math.max(stayScore, 85);

  // 7. Engagement quality
  let engagementScore = 50;
  const eng = c.profile.engagement;
  if (eng?.avgLikes != null && c.profile.followers) {
    const er = ((eng.avgLikes + (eng.avgComments ?? 0)) / c.profile.followers) * 100;
    engagementScore = er >= 5 ? 100 : er >= 3 ? 85 : er >= 1.5 ? 70 : er >= 0.7 ? 50 : 30;
  }
  if (pi?.engagementRate?.value != null) {
    const er = pi.engagementRate.value;
    engagementScore = er >= 5 ? 100 : er >= 3 ? 85 : er >= 1.5 ? 70 : er >= 0.7 ? 50 : 30;
  }

  // 8. Partnership feasibility: brand fit + low risk + recurring
  const feasibility = cl ? 0.5 * blend(cl.brandFit) + 0.3 * (cl.commercialRisk === 'low' ? 100 : cl.commercialRisk === 'medium' ? 60 : cl.commercialRisk === 'high' ? 15 : 40) + 0.2 * blend(cl.runsRecurringEvents) : 40;

  const breakdown: ScoreBreakdown = {
    bookingIntentAuthority: r(intentScore),
    provenWinterActivity: r(winterScore),
    audienceRelevance: r(audienceScore),
    estimatedVenueBudget: r(budgetScore),
    geographicFit: r(geoScore),
    expectedStayDuration: r(stayScore),
    engagementQuality: r(engagementScore),
    partnershipFeasibility: r(feasibility),
  };

  let fit = 0;
  for (const k of Object.keys(weights) as Array<keyof Weights>) fit += (breakdown[k] * weights[k]) / 100;

  // Confidence: share of judgements with evidence, data completeness, contradictions
  let confidence = confidenceFor(c, cl, !!pi);
  if (pi?.contradictions?.length) { confidence *= Math.max(0.4, 1 - 0.2 * pi.contradictions.length); gates.push('contradictions_reduce_confidence'); }

  // Disqualification
  const severe = redFlags.filter((f) => SEVERE_RED_FLAGS.some((re) => re.test(f)));
  const disqualified = severe.length > 0;
  if (disqualified) gates.push('severe_red_flag_disqualifies');

  // Tier gates
  let tier: Tier = fit >= 75 ? 'A' : fit >= 60 ? 'B' : fit >= 45 ? 'C' : 'D';
  if (tier === 'A' && !hasWinterEvidence) { tier = 'B'; gates.push('no_winter_evidence_blocks_tier_a'); }
  if (tier === 'A' && confidence < 0.4) { tier = 'B'; gates.push('low_confidence_blocks_tier_a'); }
  if (disqualified) tier = 'excluded';

  return {
    fitScore: r(fit),
    confidence: Math.round(confidence * 100) / 100,
    tier,
    breakdown,
    weightsUsed: weights,
    gates,
    redFlags,
    disqualified,
    disqualificationReason: disqualified ? severe.join('; ') : undefined,
  };
}

function r(n: number): number { return Math.round(Math.max(0, Math.min(100, n))); }

function confidenceFor(c: Candidate, cl: Classification | undefined, hasPrivate: boolean): number {
  if (!cl) return 0.15;
  const judgements: Judgement[] = [cl.decidesVenue, cl.sellsRetreats, cl.provenWinterActivity, cl.canFillGroupSize, cl.audiencePaysPremium, cl.runsRecurringEvents, cl.longStayPotential, cl.brandFit, cl.priorCommercialEvidence];
  const known = judgements.filter((x) => x.value !== null);
  const withEvidence = judgements.filter((x) => x.evidenceUrls.length > 0);
  const avgConf = known.length ? known.reduce((s, x) => s + x.confidence, 0) / known.length : 0;
  const completeness = [c.profile.followers != null, !!c.profile.bio, c.events.length > 0, c.evidence.length >= 3, !!c.profile.country].filter(Boolean).length / 5;
  let conf = 0.45 * avgConf + 0.3 * (withEvidence.length / judgements.length) + 0.25 * completeness;
  if (hasPrivate) conf = Math.min(1, conf + 0.2);
  return Math.max(0.05, Math.min(1, conf));
}

// ===== discovery/normalize.ts =====
/**
 * Candidate normalisation: extract Instagram handles from URLs, titles and
 * extracted page text; dedupe; merge evidence. Handles are the identity key.
 */

const RESERVED = new Set(['p', 'reel', 'reels', 'explore', 'stories', 'accounts', 'tv', 'about', 'legal', 'directory', 'developer', 'web', 'static', 'locations', 'tags', 'direct', 'ar', 'privacy', 'terms', 'press', 'api']);

/**
 * Canonical handle: lower-case, no leading '@', no leading or trailing periods.
 * Instagram usernames cannot start or end with a period, so a trailing '.' is
 * sentence punctuation captured by a text pattern ("More posts from x.").
 */
export function cleanHandle(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const h = raw.trim().toLowerCase().replace(/^@/, '').replace(/^\.+|\.+$/g, '');
  return /^[a-z0-9._]{1,30}$/.test(h) && !/\.\./.test(h) ? h : null;
}

/** Extract a handle from an Instagram profile URL. Returns null for post/reel URLs. */
export function handleFromUrl(url: string): string | null {
  try {
    const u = new URL(url);
    if (!/(^|\.)instagram\.com$/i.test(u.hostname)) return null;
    const seg = u.pathname.split('/').filter(Boolean);
    if (seg.length === 0) return null;
    const first = seg[0].toLowerCase();
    if (RESERVED.has(first)) return null;
    return cleanHandle(first);
  } catch {
    return null;
  }
}

/** Extract "(@handle)" from a search result title like "Name (@handle) • Instagram". */
export function handleFromTitle(title: string | undefined): string | null {
  if (!title) return null;
  const m = title.match(/\(@([a-z0-9._]{1,30})\)/i);
  return m ? cleanHandle(m[1]) : null;
}

/**
 * Extract the author handle from Tavily-extracted text of a post/reel page.
 * Instagram's logged-out page contains "Never miss a post from <handle>" and
 * "More posts from <handle>". Backslash-escaped underscores are unescaped.
 */
export function handleFromExtractedText(text: string | undefined): string | null {
  if (!text) return null;
  const t = text.replace(/\\_/g, '_');
  const patterns = [/Never miss a post from ([a-z0-9._]{1,30})/i, /More posts from ([a-z0-9._]{1,30})/i, /^([a-z0-9._]{1,30})\n•\nFollow/im];
  for (const p of patterns) {
    const m = t.match(p);
    if (m) { const h = cleanHandle(m[1]); if (h) return h; }
  }
  return null;
}

export function followersFromText(text: string | undefined): number | null {
  if (!text) return null;
  const m = text.match(/([\d.,]+)\s*([KkMm])?\s*followers/i);
  if (!m) return null;
  let n = parseFloat(m[1].replace(/,/g, ''));
  if (Number.isNaN(n)) return null;
  if (m[2]) n = n * (m[2].toLowerCase() === 'k' ? 1_000 : 1_000_000);
  return Math.round(n);
}

export function profileUrl(handle: string): string {
  return `https://www.instagram.com/${handle}/`;
}

/** Guess the market of a profile from bio text and location words. Returns null if nothing matches. */
export function guessMarket(text: string): Market | null {
  const t = text.toLowerCase();
  const rules: Array<[Market, RegExp]> = [
    ['IL', /\b(israel|tel aviv|ישראל|תל אביב|ירושלים|חיפה)\b/],
    ['GB', /\b(london|uk|united kingdom|england|scotland|manchester|bristol|brighton|edinburgh)\b/],
    ['DE', /\b(berlin|münchen|munich|hamburg|köln|cologne|deutschland|germany|frankfurt|düsseldorf)\b/],
    ['CH', /\b(zürich|zurich|schweiz|switzerland|suisse|genève|geneva|basel|bern|lausanne)\b/],
    ['NL', /\b(amsterdam|nederland|netherlands|utrecht|rotterdam|den haag|the hague)\b/],
    ['SE', /\b(sverige|sweden|stockholm|göteborg|gothenburg|malmö)\b/],
    ['DK', /\b(danmark|denmark|københavn|copenhagen|aarhus)\b/],
    ['NO', /\b(norge|norway|oslo|bergen)\b/],
    ['FI', /\b(suomi|finland|helsinki)\b/],
    ['FR', /\b(paris|france|lyon|bordeaux|marseille|nice)\b/],
  ];
  for (const [m, re] of rules) if (re.test(t)) return m;
  return null;
}

export function guessLanguage(text: string): Language {
  if (/[֐-׿]/.test(text)) return 'he';
  if (/\b(und|nicht|mit|für|retreat\b.*\bdeutsch)/i.test(text) && /[äöüß]/i.test(text)) return 'de';
  if (/\b(et|les|des|pour|avec|retraite)\b/i.test(text) && /[éèàç]/i.test(text)) return 'fr';
  if (/\b(het|een|voor|met|retreat)\b/i.test(text) && /\b(en|van|de)\b/i.test(text) && /\b(je|jij|wij)\b/i.test(text)) return 'nl';
  return 'en';
}

const WINTER_MONTH_RE = /\b(nov(ember)?|dec(ember)?|jan(uary)?|feb(ruary)?|mar(ch)?|apr(il)?|נובמבר|דצמבר|ינואר|פברואר|מרץ|אפריל|dezember|januar|februar|märz|novembre|décembre|janvier|février|mars|avril)\b/i;

/** True when the text mentions a November–April month. Cheap pre-signal; Claude confirms. */
export function mentionsWinterMonth(text: string): boolean {
  return WINTER_MONTH_RE.test(text);
}

export function mergeCandidate(existing: Candidate, incoming: Candidate): Candidate {
  const evidenceByUrl = new Map<string, Evidence>();
  for (const e of [...existing.evidence, ...incoming.evidence]) if (!evidenceByUrl.has(e.url)) evidenceByUrl.set(e.url, e);
  const markets = Array.from(new Set([...existing.markets, ...incoming.markets]));
  return {
    ...existing,
    profile: {
      ...existing.profile,
      ...Object.fromEntries(Object.entries(incoming.profile).filter(([, v]) => v !== undefined && v !== null && v !== '')),
      handle: existing.profile.handle,
    },
    markets,
    events: dedupeEvents([...existing.events, ...incoming.events]),
    evidence: Array.from(evidenceByUrl.values()),
    discoveryQueries: Array.from(new Set([...existing.discoveryQueries, ...incoming.discoveryQueries])),
    lastSeenAt: incoming.lastSeenAt > existing.lastSeenAt ? incoming.lastSeenAt : existing.lastSeenAt,
  };
}

export function dedupeEvents<T extends { title: string; startDate?: string; location?: string }>(events: T[]): T[] {
  const seen = new Map<string, T>();
  for (const ev of events) {
    const k = `${ev.title.toLowerCase().trim()}|${ev.startDate ?? ''}|${(ev.location ?? '').toLowerCase()}`;
    if (!seen.has(k)) seen.set(k, ev);
  }
  return Array.from(seen.values());
}

/** Normalises a website for sister-account detection: lower-case host + path, no scheme, no www, no trailing slash. */
export function normalizeWebsite(site: string | null | undefined): string | null {
  if (!site) return null;
  let s = site.trim().toLowerCase();
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.split(/[?#]/)[0].replace(/\/+$/, '');
  return s || null;
}

// ===== discovery/queryGenerator.ts =====
/**
 * Dynamic discovery query generator.
 *
 * Produces hundreds of search queries from the cartesian product of event type,
 * season month, destination, source market, language, niche phrases and
 * commercial-intent phrases. Queries are deterministic (same inputs → same
 * list) so a run can be resumed, and each query carries the dimensions it was
 * built from so results can be attributed.
 */

export interface QuerySpec {
  id: string;             // stable hash-like id
  query: string;
  language: Language;
  market?: Market;
  eventType?: EventType;
  /** Which discovery lane produced it. */
  lane: 'organizer_intent' | 'winter_destination' | 'competitor_venue' | 'market_language' | 'listing_site' | 'seed_expansion' | 'niche_b2b';
  /** Tavily parameters. */
  includeDomains?: string[];
  searchDepth: 'basic' | 'advanced';
  priority: number;       // 1 (highest) .. 5
}

export interface RunParameters {
  seasonStart: string;    // ISO
  seasonEnd: string;
  markets: Market[];
  eventTypes: EventType[];
  languages: Language[];
  /** Hard cap on number of queries the run may issue. */
  maxQueries: number;
  /** Optional seed handles for expansion lane. */
  seedHandles?: string[];
}

