// ===== insights/rescoring.ts =====
/**
 * Dynamic rescoring when private insights arrive. Keeps the public score
 * untouched, produces a verified score, and explains the delta.
 */

export interface RescoreResult {
  publicScore: ScoreResult;
  verifiedScore: ScoreResult;
  deltas: Array<{ criterion: keyof Weights; before: number; after: number; delta: number }>;
  fitDelta: number;
  confidenceDelta: number;
  explanation: string[];
  derived: DerivedMetrics;
}

export interface DerivedMetrics {
  storyReachToFollowers: number | null;
  relevantGeoShare: number | null;
  medianReelReach: number | null;
  historicalFillRate: number | null;
  avgTicketsPerEvent: number | null;
  instagramAttributedRegistrations: number | null;
  conversionEfficiency: number | null;   // conversions per 1k reach, when campaign data exists
}

const RELEVANT = new Set(['IL', 'GB', 'DE', 'CH', 'NL', 'SE', 'DK', 'NO', 'FI', 'FR', 'AT', 'BE', 'IE']);

export function deriveMetrics(c: Candidate, pi: PrivateInsights): DerivedMetrics {
  const followers = c.profile.followers ?? null;
  const storyReach = pi.storyReachAvg?.value ?? null;
  const geo = pi.audienceCountries?.length ? pi.audienceCountries.filter((a) => RELEVANT.has(a.country)).reduce((s, a) => s + a.share, 0) : null;
  const regs = pi.registrationsPerEvent ?? [];
  const avgTickets = regs.length ? regs.reduce((s, r) => s + r.registrations, 0) / regs.length : null;
  const fillRate = pi.eventsSoldOutCount?.value != null && pi.retreatsOrganisedCount?.value ? pi.eventsSoldOutCount.value / pi.retreatsOrganisedCount.value : null;
  const igRegs = pi.instagramAttributedShare?.value != null && avgTickets != null ? pi.instagramAttributedShare.value * avgTickets : null;
  const campaigns = (pi.priorCampaigns ?? []).filter((x) => x.conversions != null && x.clicks != null);
  const conv = campaigns.length && pi.accountsReached90d?.value ? (campaigns.reduce((s, x) => s + (x.conversions ?? 0), 0) / pi.accountsReached90d.value) * 1000 : null;
  return {
    storyReachToFollowers: storyReach != null && followers ? storyReach / followers : null,
    relevantGeoShare: geo,
    medianReelReach: pi.reelsReachMedian?.value ?? null,
    historicalFillRate: fillRate,
    avgTicketsPerEvent: avgTickets,
    instagramAttributedRegistrations: igRegs,
    conversionEfficiency: conv,
  };
}

export function rescoreWithInsights(c: Candidate, pi: PrivateInsights, opts: ScoringOptions = {}): RescoreResult {
  const publicScore = c.publicScore ?? scoreCandidate(c, { ...opts, usePrivateInsights: false });
  const withPi: Candidate = { ...c, privateInsights: pi };
  const verifiedScore = scoreCandidate(withPi, { ...opts, usePrivateInsights: true });
  const keys = Object.keys(publicScore.breakdown) as Array<keyof Weights>;
  const deltas = keys.map((k) => ({ criterion: k, before: publicScore.breakdown[k], after: verifiedScore.breakdown[k], delta: verifiedScore.breakdown[k] - publicScore.breakdown[k] }));
  const derived = deriveMetrics(c, pi);
  const explanation: string[] = [];
  for (const d of deltas) if (Math.abs(d.delta) >= 5) explanation.push(`${d.criterion}: ${d.before} → ${d.after} (${d.delta > 0 ? '+' : ''}${d.delta}).`);
  if (derived.relevantGeoShare != null) explanation.push(`Audience in preferred source markets: ${(derived.relevantGeoShare * 100).toFixed(0)}% (document-backed).`);
  if (derived.historicalFillRate != null) explanation.push(`Historical sold-out rate: ${(derived.historicalFillRate * 100).toFixed(0)}% of reported events.`);
  if (derived.avgTicketsPerEvent != null) explanation.push(`Average registrations per reported event: ${derived.avgTicketsPerEvent.toFixed(1)}.`);
  if (pi.contradictions?.length) explanation.push(`Contradictions found: ${pi.contradictions.join('; ')} — confidence reduced.`);
  if (!explanation.length) explanation.push('Private insights did not materially change the public assessment.');
  return {
    publicScore,
    verifiedScore,
    deltas,
    fitDelta: verifiedScore.fitScore - publicScore.fitScore,
    confidenceDelta: Math.round((verifiedScore.confidence - publicScore.confidence) * 100) / 100,
    explanation,
    derived,
  };
}

// ===== insights/learning.ts =====
/**
 * Feedback learning. Aggregates owner outcomes (quality / not relevant / replied /
 * booked) against score breakdowns and only proposes weight changes once enough
 * outcomes exist. Never auto-applies; never claims learning on thin data.
 */

export interface OutcomeRow {
  handle: string;
  breakdown: ScoreBreakdown;
  /** Positive = booked or replied-positively or marked quality; negative = not relevant / rejected. */
  outcome: 'positive' | 'negative';
  booked: boolean;
}

export interface LearningSnapshot {
  outcomesCount: number;
  bookedCount: number;
  positiveCount: number;
  featureStats: Record<keyof ScoreBreakdown, { positiveMean: number | null; negativeMean: number | null; separation: number | null }>;
  weightSuggestion: Weights | null;
  note: string;
}

export const MIN_OUTCOMES_FOR_SUGGESTION = 10;
export const MIN_POSITIVES_FOR_SUGGESTION = 3;

export function buildLearningSnapshot(rows: OutcomeRow[], current: Weights = DEFAULT_WEIGHTS): LearningSnapshot {
  const keys = Object.keys(DEFAULT_WEIGHTS) as Array<keyof ScoreBreakdown>;
  const pos = rows.filter((r) => r.outcome === 'positive');
  const neg = rows.filter((r) => r.outcome === 'negative');
  const mean = (xs: OutcomeRow[], k: keyof ScoreBreakdown) => (xs.length ? xs.reduce((s, r) => s + r.breakdown[k], 0) / xs.length : null);
  const featureStats = {} as LearningSnapshot['featureStats'];
  for (const k of keys) {
    const p = mean(pos, k), n = mean(neg, k);
    featureStats[k] = { positiveMean: p, negativeMean: n, separation: p != null && n != null ? p - n : null };
  }
  const enough = rows.length >= MIN_OUTCOMES_FOR_SUGGESTION && pos.length >= MIN_POSITIVES_FOR_SUGGESTION && neg.length >= MIN_POSITIVES_FOR_SUGGESTION;
  if (!enough) {
    return { outcomesCount: rows.length, bookedCount: rows.filter((r) => r.booked).length, positiveCount: pos.length, featureStats, weightSuggestion: null, note: `Not enough outcomes for calibration (${rows.length} outcomes, ${pos.length} positive, ${neg.length} negative; need ≥${MIN_OUTCOMES_FOR_SUGGESTION} with ≥${MIN_POSITIVES_FOR_SUGGESTION} on each side). Rankings remain on default/owner weights.` };
  }
  // Nudge weights toward criteria that separate positives from negatives; damped so one season cannot swing the model.
  const suggestion: Partial<Weights> = {};
  for (const k of keys) {
    const sep = featureStats[k].separation ?? 0;
    const factor = 1 + Math.max(-0.3, Math.min(0.3, sep / 100));
    suggestion[k] = current[k] * factor;
  }
  return { outcomesCount: rows.length, bookedCount: rows.filter((r) => r.booked).length, positiveCount: pos.length, featureStats, weightSuggestion: normalizeWeights(suggestion), note: 'Suggested weights derived from outcome separation; damped ±30% per criterion. Review before applying.' };
}

// ===== outreach/generator.ts =====
/**
 * Outreach draft generator. Drafts only: the product never sends messages.
 * Every draft is built from facts on the candidate record; it names a real
 * event or a real bio detail and never includes numeric prices.
 */

export type OutreachLanguage = 'en' | 'he';
/** Grammatical gender for Hebrew drafts. 'unknown' uses the plural form, the neutral register in Hebrew business writing. */
export type RecipientGender = 'female' | 'male' | 'unknown';

/** Picks the Hebrew form for the recipient's gender (plural when unknown). */
function heForm(g: RecipientGender, female: string, male: string, plural: string): string {
  return g === 'female' ? female : g === 'male' ? male : plural;
}

export interface OutreachDraft {
  track: PartnershipTrack;
  language: OutreachLanguage;
  subject: string;
  body: string;
  /** Facts from the record that the draft relies on, with their source URLs. */
  personalisationFacts: Array<{ fact: string; url?: string }>;
  whyThisTrack: string;
}

export const TRACK_LABELS: Record<PartnershipTrack, { en: string; he: string }> = {
  scouting_stay: { en: 'Scouting Stay', he: 'ביקור היכרות' },
  pilot_retreat: { en: 'Pilot Retreat', he: 'ריטריט פיילוט' },
  anchor_partnership: { en: 'Anchor Partnership', he: 'שותפות עוגן' },
  referral_partnership: { en: 'Referral Partnership', he: 'שותפות הפניות' },
};

const PRICE_RE = /(€|\$|£|₪|\beur\b|\busd\b|\bgbp\b|\bils\b)\s?\d|\d\s?(€|\$|£|₪|\beur\b|\busd\b|\bgbp\b|\bils\b)|\bper night\b.*\d|\d.*\bper night\b/i;

const TRACK_ORDER: Record<PartnershipTrack, number> = { scouting_stay: 0, pilot_retreat: 1, anchor_partnership: 2, referral_partnership: -1 };

/**
 * Pick the partnership track. The evidence rules give an upper bound; the classifier, which read
 * the posts, may recommend a more cautious track (e.g. a surf-camp operator: scouting only). Without
 * private verified data the more cautious of the two is used, so a first approach never asks for a
 * bigger commitment than the evidence supports. Referral recommendations are kept as they are.
 */
export function recommendTrack(c: Candidate): { track: PartnershipTrack; reason: string } {
  const rule = recommendTrackFromRules(c);
  const advised = c.classification?.recommendedTrack;
  if (!advised || c.privateInsights || rule.track === 'referral_partnership' || advised === 'referral_partnership') return rule;
  if (TRACK_ORDER[advised] < TRACK_ORDER[rule.track]) {
    return { track: advised, reason: `${rule.reason} The evidence review advises a ${TRACK_LABELS[advised].en} first; the more cautious track is used until private data supports more.` };
  }
  return rule;
}

function recommendTrackFromRules(c: Candidate): { track: PartnershipTrack; reason: string } {
  const cl = c.classification;
  const organiserEvents = c.events.filter((e) => e.role === 'organizer' || e.role === 'co_host');
  const winter = organiserEvents.filter((e) => e.isWinter);
  const recurring = cl?.runsRecurringEvents.value === true || organiserEvents.length >= 3;
  if (cl?.group === 'B_reaches_organizers' && organiserEvents.length === 0) return { track: 'referral_partnership', reason: 'Their audience is organisers, not participants; they can refer bookings rather than host.' };
  if (recurring && winter.length >= 1 && (cl?.decidesVenue.value === true)) return { track: 'anchor_partnership', reason: 'Runs recurring events including in winter and chooses venues directly; a multi-event commitment is realistic.' };
  if (organiserEvents.length >= 1 && (cl?.decidesVenue.value !== false)) return { track: 'pilot_retreat', reason: 'Proven organiser; a first retreat tests the partnership before committing to more.' };
  return { track: 'scouting_stay', reason: 'Organising capacity or venue authority not yet evidenced; a scouting stay allows an evaluation of the property with low commitment.' };
}

function firstName(c: Candidate): string {
  const n = c.profile.displayName?.trim();
  if (!n) return '';
  const clean = n.replace(/\(@.*?\)/, '').replace(/[|•·].*$/, '').trim();
  const w = clean.split(/\s+/)[0];
  return /^[A-Za-zÀ-ÿ֐-׿'-]{2,}$/.test(w) ? w : '';
}

/** Short, natural reference to an event for the opening line: the title, plus the place only if the title does not already name it. No raw dates. */
function eventPhrase(e: { title: string; location?: string | null }): string {
  // Leading article removed so the line reads 'your <event>' and never 'your The <event>'.
  const title = e.title.trim().replace(/[.,;:]+$/, '').replace(/^(the|a|an)\s+/i, '');
  const loc = e.location?.trim();
  if (!loc) return title;
  const key = loc.split(/[,(]/)[0].trim().toLowerCase();
  return key && title.toLowerCase().includes(key) ? title : `${title} in ${loc.split(',')[0].trim()}`;
}

function pickFacts(c: Candidate): Array<{ fact: string; url?: string }> {
  const facts: Array<{ fact: string; url?: string }> = [];
  const ev = [...c.events].filter((e) => e.role === 'organizer' || e.role === 'co_host').sort((a, b) => (b.startDate ?? '').localeCompare(a.startDate ?? ''));
  if (ev[0]) facts.push({ fact: `${ev[0].title}${ev[0].location ? ` in ${ev[0].location}` : ''}${ev[0].startDate ? ` (${ev[0].startDate})` : ''}`, url: ev[0].evidenceUrls[0] });
  if (ev[1]) facts.push({ fact: `${ev[1].title}${ev[1].location ? ` in ${ev[1].location}` : ''}`, url: ev[1].evidenceUrls[0] });
  if (c.profile.niche) facts.push({ fact: c.profile.niche });
  if (c.profile.bio && facts.length < 2) facts.push({ fact: c.profile.bio.slice(0, 120), url: c.profile.profileUrl });
  return facts.slice(0, 3);
}

export function generateOutreach(c: Candidate, track: PartnershipTrack, language: OutreachLanguage, whyThisTrack: string, options: { senderName?: string; referralRateNote?: boolean; recipientGender?: RecipientGender } = {}): OutreachDraft {
  const facts = pickFacts(c);
  const name = firstName(c);
  const firstEvent = [...c.events].filter((e) => e.role === 'organizer' || e.role === 'co_host').sort((a, b) => (b.startDate ?? '').localeCompare(a.startDate ?? ''))[0];
  const ev = firstEvent ? eventPhrase(firstEvent) : undefined;
  const sender = options.senderName ?? VILLA.propertyManager;
  const g: RecipientGender = options.recipientGender ?? 'unknown';
  const h = (female: string, male: string, plural: string) => heForm(g, female, male, plural);
  const en = {
    greeting: name ? `Hi ${name},` : 'Hi,',
    hook: ev ? `I came across your ${ev} on Instagram and the way you run your groups.` : `I came across your work on Instagram and the way you run your groups.`,
    villa: `I manage Villa Lithos, a private 9-bedroom estate in Porto Rafti, 20 minutes from Athens airport with no ferry, built for hosted groups.`,
    scouting_stay: `Between November and April we open the house to a small number of hosts for a scouting stay: a few nights to experience the property, the area and the logistics, and to see whether it fits a future retreat of yours. No obligation.`,
    pilot_retreat: `We are looking for a few hosts to run a first retreat with us this winter. We would structure it as a pilot: you bring your group, we take care of the house and the local logistics, and we shape terms together around your format.`,
    anchor_partnership: `We would like to work with a small number of hosts on a longer basis: several retreats or longer stays across the winter season, with priority dates and terms that reflect that commitment.`,
    referral_partnership: `We would like to propose a referral arrangement: when a host from your community books Villa Lithos for a retreat, you receive a referral fee on the booking. No hosting required on your side.`,
    close: `If this sounds interesting, I would be glad to share photos, floor plans and dates, and to answer any questions about winter in Attica.`,
    sign: `Warm regards,\n${sender}\nVilla Lithos, Porto Rafti\n${VILLA.website}`,
  };
  const he = {
    greeting: name ? `היי ${name},` : 'היי,',
    hook: ev ? `נתקלתי באינסטגרם ב-${ev} ${h('ובאופן שבו את מנהלת את הקבוצות שלך', 'ובאופן שבו אתה מנהל את הקבוצות שלך', 'ובאופן שבו אתם מנהלים את הקבוצות שלכם')}.` : `נתקלתי ${h('בפעילות שלך', 'בפעילות שלך', 'בפעילות שלכם')} באינסטגרם ${h('ובאופן שבו את מנהלת את הקבוצות שלך', 'ובאופן שבו אתה מנהל את הקבוצות שלך', 'ובאופן שבו אתם מנהלים את הקבוצות שלכם')}.`,
    villa: `אני מנהל את Villa Lithos, אחוזה פרטית עם 9 חדרי שינה בפורטו ראפטי, 20 דקות משדה התעופה של אתונה, בלי מעבורת, שמותאמת לאירוח קבוצות.`,
    scouting_stay: `בין נובמבר לאפריל אנחנו פותחים את הבית למספר קטן של ${h('מארחות', 'מארחים', 'מארחים')} לביקור היכרות: כמה לילות להתרשם מהנכס, מהאזור ומהלוגיסטיקה, ולבדוק אם הוא מתאים לריטריט עתידי ${h('שלך', 'שלך', 'שלכם')}. בלי התחייבות.`,
    pilot_retreat: `אנחנו מחפשים ${h('כמה מארחות שיקיימו', 'כמה מארחים שיקיימו', 'כמה מארחים שיקיימו')} איתנו ריטריט ראשון בחורף הקרוב. נבנה אותו כפיילוט: ${h('את מביאה', 'אתה מביא', 'אתם מביאים')} את הקבוצה, אנחנו דואגים לבית וללוגיסטיקה המקומית, ואת התנאים נגבש יחד סביב הפורמט ${h('שלך', 'שלך', 'שלכם')}.`,
    anchor_partnership: `נשמח לעבוד עם מספר קטן של ${h('מארחות', 'מארחים', 'מארחים')} לטווח ארוך: כמה ריטריטים או שהיות ארוכות לאורך עונת החורף, עם עדיפות בתאריכים ותנאים שמשקפים את ההתחייבות הזו.`,
    referral_partnership: `נשמח להציע הסדר הפניות: כשמארח או מארחת ${h('מהקהילה שלך', 'מהקהילה שלך', 'מהקהילה שלכם')} מזמינים את Villa Lithos לריטריט, ${h('את מקבלת', 'אתה מקבל', 'אתם מקבלים')} עמלת הפניה על ההזמנה. בלי צורך לארח ${h('בעצמך', 'בעצמך', 'בעצמכם')}.`,
    close: `אם זה מעניין, אשמח לשלוח תמונות, תוכניות קומה ותאריכים, ולענות על כל שאלה לגבי החורף באטיקה.`,
    sign: `בברכה,\n${sender}\nVilla Lithos, Porto Rafti\n${VILLA.website}`,
  };
  const t = language === 'he' ? he : en;
  const body = [t.greeting, '', t.hook, '', t.villa, '', t[track], '', t.close, '', t.sign].join('\n');
  if (PRICE_RE.test(body)) throw new Error('Outreach draft must not contain numeric prices');
  const subject = language === 'he' ? `Villa Lithos, ${TRACK_LABELS[track].he} לחורף 2026/27` : `Villa Lithos: ${TRACK_LABELS[track].en} for winter 2026/27`;
  return { track, language, subject, body, personalisationFacts: facts, whyThisTrack };
}

/** Message asking for the private data needed for Stage 2. Short, specific, never sent automatically. */
export function generateInsightsRequest(c: Candidate, language: OutreachLanguage, senderName = VILLA.propertyManager, recipientGender: RecipientGender = 'unknown'): string {
  const name = firstName(c);
  const h = (female: string, male: string, plural: string) => heForm(recipientGender, female, male, plural);
  if (language === 'he') {
    return [
      name ? `היי ${name},` : 'היי,', '',
      `כדי שנוכל לבנות הצעה שמתאימה לקבוצות ${h('שלך', 'שלך', 'שלכם')}, אשמח אם ${h('תוכלי', 'תוכל', 'תוכלו')} לשתף כמה נתונים. צילומי מסך מ-Instagram Insights מספיקים לגמרי:`,
      '1. Accounts reached ו-Views ב-90 הימים האחרונים.',
      '2. פילוח הקהל: מדינות וערים מובילות, גיל ומגדר.',
      '3. ממוצע צפיות ו-reach של סטוריז וריילס.',
      `4. לגבי הריטריטים: כמה אירועים ${h('קיימת', 'קיימת', 'קיימתם')}, כמה משתתפים בכל אחד, והאם התמלאו.`,
      '5. אם יש Media Kit או דוח מקמפיין קודם, גם הוא יעזור.', '',
      `המידע ישמש רק לבחינת שיתוף הפעולה, יישמר בצורה מאובטחת ויימחק ${h('לבקשתך', 'לבקשתך', 'לבקשתכם')}.`, '',
      `תודה,\n${senderName}\nVilla Lithos`,
    ].join('\n');
  }
  return [
    name ? `Hi ${name},` : 'Hi,', '',
    'To shape a proposal that fits your groups, could you share a few numbers? Screenshots from Instagram Insights are perfectly fine:',
    '1. Accounts reached and views for the last 90 days.',
    '2. Audience breakdown: top countries and cities, age and gender.',
    '3. Average story and Reel views and reach.',
    '4. For your retreats: how many you have run, participants per event, and whether they sold out.',
    '5. A media kit or a past campaign report, if you have one.', '',
    'This is used only to evaluate the collaboration, stored securely, and deleted on request.', '',
    `Thank you,\n${senderName}\nVilla Lithos`,
  ].join('\n');
}

// ===== ai/prompts.ts =====
/**
 * Claude prompts. Two tiers: a cost-efficient model for mass public screening
 * and a stronger model for Tier A deep analysis and private-insights
 * extraction. Structured JSON output is enforced via the schemas below.
 */

export const MODELS = {
  /** Mass classification. */
  screening: 'claude-haiku-4-5',
  /** Tier A deep analysis and insights extraction (vision). */
  deep: 'claude-sonnet-5',
  /** Lovable AI gateway equivalents, when the app runs without a BYO Anthropic key. */
  gateway: { screening: 'anthropic/claude-haiku-4-5', deep: 'anthropic/claude-sonnet-5' },
} as const;

export const SYSTEM_SCREENING = `You are the public-screening analyst of the Villa Lithos Influencer Finder.
Villa Lithos: ${VILLA.location}; ${VILLA.bedrooms.value} bedrooms; planning capacity ${VILLA.groupCapacity.value} guests (unverified); ${VILLA.minutesFromAthensAirport.value} min from Athens airport; no ferry; minimum stay ${VILLA.minimumNights.value} nights (planning). Target season: November–April. Goal: find Instagram accounts most likely to BOOK the villa for hosted groups (retreat organisers, hosts of masterminds/trainings/offsites, or accounts whose audience is such organisers). Not reach. Not followers.

You receive a candidate's public evidence: profile snippets, post captions, event pages, listing pages, each with a URL. Judge only from this evidence.
Rules:
- Every judgement needs evidenceUrls drawn from the provided URLs. If evidence is absent, set value to null and confidence to 0. Never guess.
- "sellsRetreats" is true only if she organises/sells (registration, price, spots, 'my retreat', 'join us'); promoting someone else's event or attending is false.
- "provenWinterActivity" is true only if a dated event she organised falls in November–April (any year) or she explicitly markets winter retreats.
- "canFillGroupSize" asks whether evidence shows groups of roughly 10–18 participants (e.g., '12 spots', '2 rooms left of 8', sold-out groups).
- Extract events with role (organizer/co_host/promoter), dates, location, nights, group size, price per person and currency when literally present. Mark isWinter by the event's own dates.
- redFlags: contradictions, suspicious engagement, inactive account, agency/venue account rather than a host, pricing far below premium, etc.
- commercialRisk: low/medium/high/unknown with a one-line reason in summary.
- recommendedTrack: scouting_stay | pilot_retreat | anchor_partnership | referral_partnership.
- group: A_retreat_organizer | B_reaches_organizers | C_high_value_host | none.
Output JSON only, matching the schema.`;

export const SYSTEM_DEEP = `${SYSTEM_SCREENING}

You are now running the deep analysis for a Tier A candidate. In addition: weigh brand fit against a private luxury estate (aesthetics, audience tone), estimate commercial capacity (participants × price → event revenue, as an explicit estimate with the inputs you used), note missing information that would most change the recommendation, and write a 4–6 sentence summary a property manager can act on. Mark every number as verified_public_fact, evidence_supported_inference or ai_estimate.`;

export const SYSTEM_INSIGHTS_EXTRACTION = `You extract performance data from documents an influencer shared with Villa Lithos: Instagram Insights screenshots or exports, media kits, campaign reports, retreat sales reports.
Rules:
- Record only values literally visible in the documents. For each value give the document reference (file name/page) and the reporting period if shown.
- A screenshot is "document_backed", not independently verified. Never upgrade provenance.
- Identify the reporting period of each metric (e.g., 'Last 90 days', 'Jan 1–Mar 31').
- Compare documents with each other and with the public profile data provided. List contradictions explicitly (e.g., followers in media kit vs public count; reach claims inconsistent with follower count).
- Do not estimate missing metrics. Leave them absent.
- Output JSON matching the PrivateInsights schema.`;

/** JSON schema used for structured output of the screening/deep steps. */
export const CLASSIFICATION_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['group', 'decidesVenue', 'sellsRetreats', 'provenWinterActivity', 'canFillGroupSize', 'audiencePaysPremium', 'runsRecurringEvents', 'longStayPotential', 'brandFit', 'priorCommercialEvidence', 'commercialRisk', 'recommendedTrack', 'redFlags', 'missingInformation', 'summary', 'events', 'profile'],
  properties: {
    group: { enum: ['A_retreat_organizer', 'B_reaches_organizers', 'C_high_value_host', 'none'] },
    ...Object.fromEntries(['decidesVenue', 'sellsRetreats', 'provenWinterActivity', 'canFillGroupSize', 'audiencePaysPremium', 'runsRecurringEvents', 'longStayPotential', 'brandFit', 'priorCommercialEvidence'].map((k) => [k, {
      type: 'object', additionalProperties: false, required: ['value', 'confidence', 'evidenceUrls'],
      properties: { value: { type: ['boolean', 'null'] }, confidence: { type: 'number', minimum: 0, maximum: 1 }, evidenceUrls: { type: 'array', items: { type: 'string' } }, note: { type: 'string' } },
    }])),
    commercialRisk: { enum: ['low', 'medium', 'high', 'unknown'] },
    recommendedTrack: { enum: ['scouting_stay', 'pilot_retreat', 'anchor_partnership', 'referral_partnership'] },
    redFlags: { type: 'array', items: { type: 'string' } },
    missingInformation: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
    events: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['title', 'role', 'isWinter', 'provenance', 'evidenceUrls'],
        properties: {
          title: { type: 'string' }, eventType: { type: 'string' }, startDate: { type: 'string' }, endDate: { type: 'string' }, nights: { type: 'number' }, location: { type: 'string' }, country: { type: 'string' },
          groupSize: { type: 'number' }, pricePerPerson: { type: 'number' }, currency: { type: 'string' }, soldOut: { type: 'boolean' },
          role: { enum: ['organizer', 'co_host', 'promoter', 'unknown'] }, isWinter: { type: 'boolean' },
          provenance: { enum: ['verified_public_fact', 'evidence_supported_inference', 'ai_estimate', 'unknown'] }, evidenceUrls: { type: 'array', items: { type: 'string' } },
        },
      },
    },
    profile: {
      type: 'object', additionalProperties: false,
      properties: { displayName: { type: 'string' }, country: { type: 'string' }, languages: { type: 'array', items: { type: 'string' } }, niche: { type: 'string' }, markets: { type: 'array', items: { type: 'string' } } },
    },
  },
} as const;

export function buildScreeningUserMessage(input: { handle: string; profileUrl: string; bio?: string | null; followers?: number | null; website?: string | null; evidence: Array<{ url: string; title?: string; excerpt?: string; kind?: string }> }): string {
  const lines = [
    `Candidate: @${input.handle} (${input.profileUrl})`,
    `Bio: ${input.bio ?? 'unknown'}`,
    `Followers: ${input.followers ?? 'unknown'}`,
    `Website: ${input.website ?? 'unknown'}`,
    '',
    'Evidence (URL | kind | title | excerpt):',
    ...input.evidence.slice(0, 40).map((e) => `- ${e.url} | ${e.kind ?? 'other'} | ${(e.title ?? '').slice(0, 120)} | ${(e.excerpt ?? '').replace(/\s+/g, ' ').slice(0, 500)}`),
  ];
  return lines.join('\n');
}
